// Everything times off the VO. content/timeline.json is generated by scripts/timeline.py from content/beats.json and
// public/vo/manifest.json, so a re-voice moves every cut, sound and caption with it.
import tl from "../../content/timeline.json";
import film from "../../content/beats.json";
import type { Film, TimeRef } from "./types";

export type Word = { word: string; start: number; end: number };
export type TLBeat = { id: string; file: string | null; startSec: number; durationSec: number; highlight?: string; words: Word[] };

export const FPS = 30;
export const TIMELINE = tl as unknown as { totalSec: number; beats: TLBeat[] };
export const FILM = film as unknown as Film;
export const TOTAL_FRAMES = Math.ceil(TIMELINE.totalSec * FPS);

export const sec = (s: number) => Math.round(s * FPS);

const byId = Object.fromEntries(TIMELINE.beats.map((b) => [b.id, b]));
export const beat = (id: string) => {
  const b = byId[id];
  if (!b) throw new Error(`no beat "${id}" in content/timeline.json. Run npm run vo:scratch or npm run vo:build.`);
  return b;
};

/** Absolute frame where beat `id` starts. */
export const bStart = (id: string) => sec(beat(id).startSec);
/** Absolute frame where beat `id` ends (its last word, or its hold for a beat with no VO). */
export const bEnd = (id: string) => {
  const b = beat(id);
  return sec(b.words.length ? b.words[b.words.length - 1].end : b.startSec + b.durationSec);
};

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9%'-]/g, "");
/** Absolute frame of the n-th occurrence (0-based) of a word in beat `id`. Ignores case and punctuation. */
export const w = (id: string, word: string, n = 0) => {
  const hit = beat(id).words.filter((x) => norm(x.word) === norm(word))[n];
  if (!hit) throw new Error(`word "${word}" (occurrence ${n}) is not in beat ${id}`);
  return sec(hit.start);
};

/** Resolve a time reference from beats.json to an absolute frame. Default beat = the one that owns the reference. */
export const at = (ref: TimeRef | undefined, ownerBeat: string): number => {
  if (ref === undefined || ref === "start") return bStart(ownerBeat);
  if (ref === "end") return bEnd(ownerBeat);
  if (typeof ref === "number") return bStart(ownerBeat) + sec(ref);
  if (typeof ref === "string") return w(ownerBeat, ref);
  const b = ref.beat ?? ownerBeat;
  const base = ref.word ? w(b, ref.word, ref.n ?? 0) : ref.end ? bEnd(b) : bStart(b);
  return base + (ref.frames ?? 0);
};

/** VO-active envelope (0..1) per absolute frame, for ducking the music. */
export const voEnvelope = (() => {
  const arr = new Float32Array(TOTAL_FRAMES + 1);
  for (const b of TIMELINE.beats) {
    if (!b.words.length) continue;
    const a = sec(b.startSec - 0.12);
    const z = sec(b.words[b.words.length - 1].end + 0.25);
    for (let f = Math.max(0, a); f <= Math.min(TOTAL_FRAMES, z); f++) arr[f] = 1;
  }
  const out = new Float32Array(arr.length);
  const R = 8;
  for (let f = 0; f < arr.length; f++) {
    let m = 0;
    for (let k = -R; k <= R; k++) {
      const g = f + k;
      if (g >= 0 && g < arr.length && arr[g] > 0) m = Math.max(m, 1 - Math.abs(k) / (R + 1));
    }
    out[f] = m;
  }
  return out;
})();
